import json

# Generate corrected output (25 rows)
def pattern_to_rows(rows=25, cols=26):
    result = []
    for r in range(rows):
        row = [0] * cols

        c5 = r + 9
        if c5 < cols:
            row[c5] = 5

        if r >= 2:
            c4 = r - 2
            if c4 < cols:
                row[c4] = 4

        if r >= 8:
            if r == 8:
                row[0] = 3
            else:
                c1, c2 = r - 9, r - 8
                if c1 < cols and c2 < cols:
                    row[c1] = 3
                    row[c2] = 3

        result.append(row)

    return result

output = pattern_to_rows()

# Save to file
with open('/tmp/final_output.json', 'w') as f:
    json.dump(output, f)

print("Final solution (25 rows, 26x26 each):")
print(json.dumps(output, indent=2))

