# Only keep the 3s pattern AND extend 4s and 5s within the main triangle
rows = 26
cols = 26

def get_row(r):
    row = [0] * cols
    if r <= 16:
        c5 = r + 9
        if c5 >= 0:
            row[c5] = 5  # only include if in range
    if r >= 2:
        c4 = r - 2
        if c4 >= 0:
            row[c4] = 4  # only include if in range
    if r == 8:
        row[0] = 3
    elif r >= 9 and (r-9) < cols:
        row[r-9] = 3
        if r-8 < cols:
            row[r-8] = 3
    return row

grid = [get_row(r) for r in range(rows)]
